import { useCallback, useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bookmark, BookOpen, BriefcaseBusiness, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Clock3, Compass, ExternalLink, Filter, GraduationCap, LayoutDashboard, LogOut, Menu, MessageCircle, Moon, MoreHorizontal, Search, Send, Settings, ShieldCheck, Sparkles, Sun, Target, TrendingUp, X, Zap } from 'lucide-react';
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis } from 'recharts';
import { api, type Job, type Role, type Step, type UserProfile, supabase } from './lib';
import type { CSSProperties, FormEvent, ReactNode } from 'react';

type Page = 'overview'|'roles'|'jobs'|'mentor'|'journey'|'profile';
const blankProfile: UserProfile = {name:'',college:'',branch:'',year:'',target_role:'',target_companies:[],theme:'light'};
const nav: {id:Page;label:string;icon:typeof LayoutDashboard;group:string}[] = [
  {id:'overview',label:'Overview',icon:LayoutDashboard,group:'WORKSPACE'},
  {id:'roles',label:'Explore roles',icon:Compass,group:'DISCOVER'},
  {id:'jobs',label:'Job openings',icon:BriefcaseBusiness,group:'DISCOVER'},
  {id:'mentor',label:'AI mentor',icon:Sparkles,group:'GROW'},
  {id:'journey',label:'My journey',icon:TrendingUp,group:'GROW'},
  {id:'profile',label:'Profile & settings',icon:Settings,group:'ACCOUNT'}
];
function weeklyActivity(progress:any){const today=new Date();today.setHours(0,0,0,0);return Array.from({length:7},(_,index)=>{const day=new Date(today);day.setDate(today.getDate()-6+index);const key=day.toDateString();const roadmap=(progress.roadmap??[]).filter((s:any)=>s.completed&&s.completed_at&&new Date(s.completed_at).toDateString()===key).length;const skills=(progress.checklist??[]).filter((s:any)=>s.completed&&s.updated_at&&new Date(s.updated_at).toDateString()===key).length;return {day:day.toLocaleDateString(undefined,{weekday:'short'}),done:roadmap+skills}})}
function initials(name:string){return name.trim().split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'CN'}
function prettyDate(s:string){return new Date(`${s}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'})}
function Logo(){return <div className="brand"><div className="brand-mark"><Compass size={18}/></div><span>career<span className="brand-light">navigator</span></span></div>}

export function App(){
  const [session,setSession]=useState<any>(null); const [authReady,setAuthReady]=useState(!supabase); const [page,setPage]=useState<Page>('overview'); const [showAuth,setShowAuth]=useState(false);
  const [profile,setProfile]=useState<UserProfile>(blankProfile); const [roles,setRoles]=useState<Role[]>([]); const [jobs,setJobs]=useState<Job[]>([]); const [progress,setProgress]=useState<any>({checklist:[],roadmap:[],saved:[]});
  const [loading,setLoading]=useState(false); const [notice,setNotice]=useState(''); const [authError,setAuthError]=useState(''); const [authMode,setAuthMode]=useState<'login'|'signup'>('login'); const [mobileNav,setMobileNav]=useState(false);
  const reload=useCallback(async(s:any)=>{ if(!s)return; setLoading(true); try { const [p,r,j,g]=await Promise.all([api<UserProfile>('/api/profile',s),api<Role[]>('/api/roles',s),api<Job[]>('/api/jobs',s),api<any>('/api/progress',s)]); setProfile(p); setRoles(r); setJobs(j); setProgress(g); } catch(e){setNotice((e as Error).message)} finally{setLoading(false)} },[]);
  useEffect(()=>{ if(!supabase)return; supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true); if(data.session)void reload(data.session)}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);if(s)void reload(s);else {setProfile(blankProfile);setProgress({checklist:[],roadmap:[],saved:[]})}}); return ()=>subscription.unsubscribe(); },[reload]);
  useEffect(()=>{document.documentElement.dataset.theme=profile.theme||'light'},[profile.theme]);
  useEffect(()=>{if(!notice)return;const id=setTimeout(()=>setNotice(''),4600);return()=>clearTimeout(id)},[notice]);
  async function signIn(e:FormEvent<HTMLFormElement>){e.preventDefault();setAuthError('');if(!supabase){setAuthError('Add your Supabase URL and anon key to .env to connect your workspace.');return}const fd=new FormData(e.currentTarget);const email=String(fd.get('email'));const password=String(fd.get('password'));const {error}=authMode==='signup'?await supabase.auth.signUp({email,password}):await supabase.auth.signInWithPassword({email,password});if(error)setAuthError(error.message);else if(authMode==='signup')setAuthError('Check your email to confirm your account, then sign in.')}
  async function demoLogin(){setAuthError('');if(!supabase){setAuthError('Add your Supabase URL and anon key to .env. In Supabase Auth, enable anonymous sign-ins for one-click demo access.');return}const {error}=await supabase.auth.signInAnonymously();if(error)setAuthError(error.message)}
  async function signOut(){await supabase?.auth.signOut()}
  async function saveProfile(next:UserProfile){setProfile(next);try{await api('/api/profile',session,{method:'PUT',body:JSON.stringify(next)});setNotice('Your profile is up to date.')}catch(e){setNotice((e as Error).message)}}
  if(!authReady)return <div className="boot"><Logo/><div className="spinner"/></div>;
  if(!session)return showAuth?<AuthScreen onSubmit={signIn} mode={authMode} setMode={setAuthMode} onDemo={demoLogin} error={authError} onBack={()=>setShowAuth(false)}/>:<Landing onGetStarted={()=>{setAuthMode('signup');setShowAuth(true)}} onSignIn={()=>{setAuthMode('login');setShowAuth(true)}} onDemo={demoLogin} error={authError}/>;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav?'sidebar-open':''}`}><div className="sidebar-head"><Logo/><button className="icon-btn mobile-close" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><X size={18}/></button></div>
      <div className="workspace-switch"><div className="workspace-logo">{initials(profile.college||profile.name)}</div><span><b>{profile.college||'My workspace'}</b><small>Student workspace</small></span><ChevronDown size={15}/></div>
      <nav className="side-nav">{['WORKSPACE','DISCOVER','GROW','ACCOUNT'].map(group=><div className="nav-group" key={group}><div className="nav-label">{group}</div>{nav.filter(n=>n.group===group).map(item=><button key={item.id} className={`nav-item ${page===item.id?'active':''}`} onClick={()=>{setPage(item.id);setMobileNav(false)}}><item.icon size={17}/><span>{item.label}</span>{item.id==='jobs'&&<span className="nav-count">{jobs.length}</span>}{item.id==='mentor'&&<span className="nav-new">NEW</span>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="plan-card"><div className="plan-icon"><Sparkles size={15}/></div><b>Your next chapter starts here</b><p>Small steps add up. Keep your momentum going.</p><button onClick={()=>setPage('mentor')}>Open your roadmap <ArrowRight size={14}/></button></div><button className="user-switch" onClick={()=>setPage('profile')}><div className="avatar">{initials(profile.name)}</div><span><b>{profile.name||'Your profile'}</b><small>{profile.target_role||'Choose your direction'}</small></span><MoreHorizontal size={17}/></button></div>
    </aside>
    {mobileNav&&<button className="scrim" aria-label="Close menu" onClick={()=>setMobileNav(false)}/>}
    <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="icon-btn mobile-menu" aria-label="Open navigation" onClick={()=>setMobileNav(true)}><Menu size={19}/></button><div className="breadcrumb">Workspace <ChevronRight size={14}/><b>{nav.find(n=>n.id===page)?.label}</b></div></div><div className="topbar-actions"><button className="search-shortcut" onClick={()=>setPage('jobs')}><Search size={15}/><span>Search openings</span><kbd>/</kbd></button><button className="icon-btn" aria-label="Help" onClick={()=>setNotice('Need a hand? Start with the AI mentor or explore a role to see your next steps.')}><CircleHelp size={18}/></button><span className="top-divider"/><button className="avatar avatar-top" onClick={()=>setPage('profile')} title="Open profile">{initials(profile.name)}</button></div></header>
      <section className="page-body"><AnimatePresence mode="wait"><motion.div key={page} initial={{opacity:0,y:7}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.18}}>{loading&&page!=='overview'?<LoadingState/>:page==='overview'?<Overview profile={profile} jobs={jobs} progress={progress} loading={loading} setPage={setPage}/>:page==='roles'?<RoleExplorer roles={roles} profile={profile} session={session} progress={progress} setProgress={setProgress} notify={setNotice}/>:page==='jobs'?<JobsPage jobs={jobs} session={session} progress={progress} reload={()=>reload(session)} notify={setNotice}/>:page==='mentor'?<Mentor roles={roles} profile={profile} session={session} progress={progress} setProgress={setProgress} notify={setNotice}/>:page==='journey'?<Journey profile={profile} progress={progress} jobs={jobs} setPage={setPage}/>:<ProfilePage profile={profile} save={saveProfile} signOut={signOut}/>}</motion.div></AnimatePresence></section>
    </main>{notice&&<div className="toast" role="status"><CheckCircle2 size={17}/>{notice}<button onClick={()=>setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}
  </div>
}

function Landing({onGetStarted,onSignIn,onDemo,error}:{onGetStarted:()=>void;onSignIn:()=>void;onDemo:()=>void;error:string}){return <div className="landing"><header className="landing-nav"><Logo/><div className="landing-nav-right"><button className="landing-signin" onClick={onSignIn}>Sign in</button><button className="btn-primary" onClick={onGetStarted}>Get started <ArrowRight size={15}/></button></div></header><main><section className="landing-hero"><div className="landing-hero-copy"><div className="landing-kicker"><span className="live-dot"/> A CLEARER PATH FOR WHAT’S NEXT</div><h1>Your next chapter,<br/><em>mapped.</em></h1><p>Find the skills, companies, and opportunities that fit your ambitions. Then make a plan to get there—one thoughtful step at a time.</p><div className="landing-actions"><button className="btn-primary" onClick={onGetStarted}>Get started <ArrowRight size={16}/></button><button className="landing-demo" onClick={onDemo}><Sparkles size={15}/> Explore the demo</button></div>{error&&<div className="auth-error">{error}</div>}<div className="landing-proof"><span><Check size={13}/> A plan built around you</span><span><Check size={13}/> Free to get started</span></div></div><div className="landing-visual"><div className="landing-halo halo-one"/><div className="landing-halo halo-two"/><div className="landing-orbit-card"><div className="orbit-card-top"><span className="orbit-dot"/> YOUR CAREER PATH <MoreHorizontal size={15}/></div><div className="orbit-card-title">A direction that<br/>feels like <em>yours.</em></div><div className="orbit-timeline"><div className="timeline-line"/><div className="timeline-entry"><i className="timeline-check"><Check size={10}/></i><span><b>Explore your strengths</b><small>Foundation · 2 weeks</small></span><CheckCircle2 size={15}/></div><div className="timeline-entry current"><i className="timeline-check"><span/></i><span><b>Build core skills</b><small>Your next step · 6 weeks</small></span><ArrowRight size={14}/></div><div className="timeline-entry future"><i className="timeline-check"/><span><b>Create something real</b><small>Project · 4 weeks</small></span></div></div><div className="orbit-card-bottom"><span><span className="live-dot"/> MOMENTUM IS BUILDING</span><b>02 <small>/ 05</small></b></div></div><div className="float-badge badge-top"><span><Sparkles size={14}/></span><div><b>Thoughtful guidance</b><small>Made for your goals</small></div></div><div className="float-badge badge-bottom"><span><BriefcaseBusiness size={15}/></span><div><b>New opportunities</b><small>Worth exploring</small></div><i>3</i></div></div></section><section className="landing-trust"><span>THE PIECES OF YOUR NEXT MOVE</span><div><b><Target size={14}/> CLARITY</b><i/><b><Compass size={14}/> DIRECTION</b><i/><b><TrendingUp size={14}/> MOMENTUM</b></div></section><section className="landing-features"><div className="landing-section-heading"><span className="eyebrow">A LITTLE MORE CLARITY</span><h2>Everything you need to move forward.</h2><p>Less guesswork. More meaningful progress.</p></div><div className="feature-grid"><article className="feature-card"><div className="feature-icon lavender"><Target size={19}/></div><span className="feature-number">01 / FIND YOUR DIRECTION</span><h3>Role skills</h3><p>See the skills that matter for the career you want. Build confidence with a practical checklist and learning order.</p><div className="feature-foot"><span>10 curated role guides</span><ArrowUpRight size={15}/></div></article><article className="feature-card"><div className="feature-icon peach"><BriefcaseBusiness size={19}/></div><span className="feature-number">02 / FIND YOUR OPPORTUNITY</span><h3>Company jobs</h3><p>Explore openings from leading teams, understand the deadlines, and save the roles you want to come back to.</p><div className="feature-foot"><span>Openings with useful context</span><ArrowUpRight size={15}/></div></article><article className="feature-card"><div className="feature-icon mint"><Sparkles size={19}/></div><span className="feature-number">03 / KEEP YOUR MOMENTUM</span><h3>AI mentor</h3><p>Turn your goals into a roadmap you can actually follow—with supportive guidance at every step.</p><div className="feature-foot"><span>A plan that grows with you</span><ArrowUpRight size={15}/></div></article></div></section></main><footer className="landing-footer"><Logo/><span>Built to help you find your way forward.</span><small>© {new Date().getFullYear()} Career Navigator</small></footer></div>}

function AuthScreen({onSubmit,mode,setMode,onDemo,error,onBack}:{onSubmit:(e:FormEvent<HTMLFormElement>)=>void;mode:'login'|'signup';setMode:(m:'login'|'signup')=>void;onDemo:()=>void;error:string;onBack:()=>void}){return <div className="auth-screen"><div className="auth-aside"><div className="auth-art"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="art-dot"/><div className="art-window"><div className="art-window-top"><span/><span/><span/></div><div className="art-window-content"><div className="art-kicker"><span/> YOUR NEXT CHAPTER</div><div className="art-title">Make your<br/>next move<br/><em>count.</em></div><div className="art-progress"><span/><span/><span/><span/><span/></div><div className="art-card"><div className="art-card-icon"><Target size={15}/></div><div><b>Career clarity</b><small>Your goals, within reach</small></div><ArrowUpRight size={15}/></div></div></div><div className="auth-quote"><div className="quote-stars">✳ ✳ ✳ ✳ ✳</div><p>“The right direction changes everything. Start with one small step.”</p><small>— Your Career Navigator</small></div></div><div className="auth-brand"><Logo/><span>Thoughtful tools for your next chapter.</span></div></div><div className="auth-main"><div className="auth-main-inner"><button className="auth-back" onClick={onBack}><ArrowRight size={13}/> Back to Career Navigator</button><div className="auth-mobile-brand"><Logo/></div><div className="auth-overline"><span className="live-dot"/> YOUR FUTURE, IN FOCUS</div><h1>{mode==='login'?'Welcome back.':'Your next chapter starts here.'}</h1><p className="auth-sub">{mode==='login'?'Sign in to pick up where you left off.':'Make a little progress every day.'}</p><form onSubmit={onSubmit} className="auth-form"><label>Email address<input name="email" type="email" placeholder="you@university.edu" autoComplete="email" required/></label><label>Password<input name="password" type="password" placeholder="At least 8 characters" autoComplete={mode==='login'?'current-password':'new-password'} minLength={8} required/></label><button type="submit" className="btn-primary auth-submit">{mode==='login'?'Sign in':'Create your account'}<ArrowRight size={16}/></button></form>{error&&<div className="auth-error" role="alert">{error}</div>}<div className="auth-divider"><span/>or<span/></div><button className="btn-demo" onClick={onDemo}><Sparkles size={16}/> Try the demo workspace</button><div className="auth-switch">{mode==='login'?"New to Career Navigator?":"Already have an account?"} <button onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'Create an account':'Sign in'}</button></div><div className="auth-foot"><ShieldCheck size={14}/> Your information stays private and secure.</div></div></div></div>}

function PageHeading({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle:string;action?:ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function LoadingState(){return <div className="loading-state" aria-label="Loading Career Navigator"><div className="skeleton loading-heading"/><div className="skeleton loading-subheading"/><div className="loading-grid"><div className="skeleton loading-card"/><div className="skeleton loading-card"/><div className="skeleton loading-card"/></div><div className="skeleton loading-wide"/></div>}
function Overview({profile,jobs,progress,loading,setPage}:{profile:UserProfile;jobs:Job[];progress:any;loading:boolean;setPage:(p:Page)=>void}){const open=jobs.filter(j=>j.status==='Open'||j.status==='Closing Soon').slice(0,3);const activity=weeklyActivity(progress);const done=(progress.roadmap??[]).filter((x:any)=>x.completed).length;const total=(progress.roadmap??[]).length;const percent=total?Math.round(done/total*100):0;const first= (progress.roadmap??[]).find((x:any)=>!x.completed);return <>
  <PageHeading eyebrow={new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date()).toUpperCase()} title={`${new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening'}${profile.name?`, ${profile.name.split(' ')[0]}`:''} ✨`} subtitle="A little progress today goes a long way." action={<button className="btn-primary" onClick={()=>setPage('mentor')}><Sparkles size={16}/> Continue with mentor</button>}/>
  <div className="welcome-banner"><div className="welcome-copy"><span className="banner-eyebrow"><span className="live-dot"/> YOUR CAREER, IN MOTION</span><h2>{profile.target_role?`Your ${profile.target_role} journey is taking shape.`:'Your next chapter is closer than you think.'}</h2><p>{profile.target_role?'Keep building skills that open the right doors.':'Explore a role that excites you. We’ll help you map the way there.'}</p><button className="btn-light" onClick={()=>setPage(profile.target_role?'journey':'roles')}>{profile.target_role?'View my journey':'Explore career paths'}<ArrowRight size={15}/></button></div><div className="banner-art"><div className="banner-ring ring-a"/><div className="banner-ring ring-b"/><div className="banner-moon"/><div className="banner-star star-a">✳</div><div className="banner-star star-b">✦</div><div className="banner-planet"/></div><div className="banner-index">01 <span/> 04</div></div>
  <div className="section-row"><div><h2 className="section-title">Your snapshot</h2><p className="section-sub">A quick look at where you are today</p></div><button className="text-link" onClick={()=>setPage('journey')}>View journey <ArrowRight size={14}/></button></div>
  <div className="metric-grid"><Metric icon={Target} label="Journey progress" value={`${percent}%`} note={total?`${done} of ${total} steps complete`:'Your roadmap is ready when you are'} tone="violet" trend={total?'+12% this month':undefined} onClick={()=>setPage('journey')}/><Metric icon={Zap} label="Skills mastered" value={`${(progress.checklist??[]).filter((x:any)=>x.completed).length}`} note="Skills checked off" tone="amber" onClick={()=>setPage('roles')}/><Metric icon={Bookmark} label="Saved openings" value={`${(progress.saved??[]).length}`} note="Keep good fits close" tone="blue" onClick={()=>setPage('jobs')}/><Metric icon={BriefcaseBusiness} label="Open opportunities" value={`${jobs.filter(x=>x.status==='Open'||x.status==='Closing Soon').length}`} note="Matched to your interests" tone="green" onClick={()=>setPage('jobs')}/></div>
  <div className="content-grid"><section className="panel progress-panel"><div className="panel-heading"><div><h3>Your weekly progress</h3><p>Completed steps and skills over seven days</p></div><span className="select-lite">This week</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity} margin={{top:12,right:5,left:-22,bottom:0}}><defs><linearGradient id="progressGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7160e8" stopOpacity={.16}/><stop offset="100%" stopColor="#7160e8" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line-soft)" strokeDasharray="3 5"/><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'var(--muted)'}} dy={10}/><Tooltip contentStyle={{border:'1px solid var(--line)',borderRadius:12,background:'var(--surface)',fontSize:12}}/><Area type="monotone" dataKey="done" stroke="#7160e8" strokeWidth={2.5} fill="url(#progressGradient)" activeDot={{r:5,strokeWidth:3,stroke:'#fff'}}/></AreaChart></ResponsiveContainer></div><div className="chart-footer"><span><i className="legend-dot"/>Completions</span><b>{activity.reduce((n,d)=>n+d.done,0)} this week</b></div></section>
  <section className="panel next-panel"><div className="panel-heading"><div><h3>Up next</h3><p>One focused step at a time</p></div><span className="soft-icon"><Clock3 size={16}/></span></div>{first?<div className="next-step"><div className="step-number">01</div><div className="step-tag">{first.phase}</div><h4>{first.title}</h4><p>{first.goal}</p><div className="next-meta"><span><Clock3 size={13}/>{first.estimate}</span><button onClick={()=>setPage('mentor')}>Open roadmap <ArrowRight size={13}/></button></div></div>:<div className="empty-mini"><div className="empty-glyph"><Sparkles size={20}/></div><b>Your roadmap is waiting</b><span>Tell your mentor where you want to go.</span><button className="text-link" onClick={()=>setPage('mentor')}>Create my roadmap <ArrowRight size={14}/></button></div>}</section></div>
  <div className="section-row section-row-jobs"><div><h2 className="section-title">Opportunities to explore</h2><p className="section-sub">Fresh openings for your next move</p></div><button className="text-link" onClick={()=>setPage('jobs')}>All openings <ArrowRight size={14}/></button></div>
  <div className="job-preview-grid">{loading?<><div className="skeleton job-skeleton"/><div className="skeleton job-skeleton"/><div className="skeleton job-skeleton"/></>:open.length?open.map(j=><JobPreview key={j.id} job={j} onClick={()=>setPage('jobs')}/>):<div className="empty-state"><BriefcaseBusiness size={22}/><b>No open roles right now</b><span>Check back soon or explore all listings.</span></div>}</div>
  </>}
function Metric({icon:Icon,label,value,note,tone,trend,onClick}:{icon:any;label:string;value:string;note:string;tone:string;trend?:string;onClick:()=>void}){return <button className="metric-card" onClick={onClick}><div className={`metric-icon ${tone}`}><Icon size={17}/></div><div className="metric-top"><span>{label}</span>{trend&&<i className="metric-trend">{trend}</i>}</div><div className="metric-value">{value}</div><div className="metric-note">{note}</div><ArrowUpRight className="metric-arrow" size={15}/></button>}
function JobPreview({job,onClick}:{job:Job;onClick:()=>void}){return <button className="job-preview" onClick={onClick}><div className="company-line"><CompanyMark company={job.company}/><div><b>{job.company}</b><small>{job.location}</small></div><span className={`status status-${job.status.toLowerCase().replace(' ','-')}`}>{job.status}</span></div><h3>{job.title}</h3><div className="job-preview-foot"><span>{job.role}</span><span><CalendarDays size={13}/> Closes {prettyDate(job.closes_at)}</span></div></button>}
function CompanyMark({company}:{company:string}){return <div className={`company-mark ${company.toLowerCase()}`}>{company==='Google'?<span className="google-g">G</span>:company==='Microsoft'?<span className="ms-grid"><i/><i/><i/><i/></span>:<span className="amazon-a">a</span>}</div>}

function RoleExplorer({roles,profile,session,progress,setProgress,notify}:{roles:Role[];profile:UserProfile;session:any;progress:any;setProgress:(v:any)=>void;notify:(s:string)=>void}){
 const [selected,setSelected]=useState('');const [q,setQ]=useState('');const [suggest,setSuggest]=useState(false);const [activeTab,setActiveTab]=useState('Skills');const [company,setCompany]=useState('Google');
 useEffect(()=>{if(roles.length&&!selected)setSelected(roles.find(r=>r.name===profile.target_role)?.id??roles[0].id)},[roles,profile.target_role]);
 const role=roles.find(r=>r.id===selected);const matches=roles.filter(r=>r.name.toLowerCase().includes(q.toLowerCase())).slice(0,5);const items=role?.skills??[];const saved=(progress.checklist??[]).filter((x:any)=>x.role_id===role?.id);const checked=(n:string)=>Boolean(saved.find((x:any)=>x.skill_name===n)?.completed);
 async function toggleSkill(name:string){if(!role)return;const list=items.map(s=>({skill_name:s.name,completed:s.name===name?!checked(name):checked(s.name)}));try{await api('/api/progress',session,{method:'PUT',body:JSON.stringify({role_id:role.id,checklist:list,roadmap:[]})});const updatedAt=new Date().toISOString();setProgress({...progress,checklist:[...(progress.checklist??[]).filter((x:any)=>x.role_id!==role.id),...list.map(x=>({...x,role_id:role.id,updated_at:updatedAt}))]})}catch(e){notify((e as Error).message)}}
 const grouped=['Core','Tools','Soft skills'];const total=items.length;const completed=items.filter(s=>checked(s.name)).length;
 return <><PageHeading eyebrow="DISCOVER YOUR DIRECTION" title="Explore a role" subtitle="Get a clear picture of the skills and preparation that matter." action={<span className="catalog-count"><span className="live-dot"/>{roles.length} role guides</span>}/>
 <section className="role-picker panel"><div className="role-picker-icon"><Compass size={19}/></div><div className="role-picker-copy"><b>Which role are you curious about?</b><span>Start with a direction. You can change it anytime.</span></div><div className="role-select-wrap"><Search size={16}/><input value={role&&!q?role.name:q} placeholder="Search roles…" onFocus={()=>{setQ('');setSuggest(true)}} onChange={e=>{setQ(e.target.value);setSuggest(true)}} onKeyDown={e=>{if(e.key==='Enter'&&matches[0]){setSelected(matches[0].id);setQ('');setSuggest(false)}}}/><ChevronDown size={15}/>{suggest&&<><button className="suggest-dismiss" onClick={()=>setSuggest(false)} aria-label="Close suggestions"/><div className="role-suggestions">{matches.map(r=><button key={r.id} onClick={()=>{setSelected(r.id);setQ('');setSuggest(false)}}><span className="suggest-icon"><BriefcaseBusiness size={15}/></span><span><b>{r.name}</b><small>{r.category}</small></span><ArrowUpRight size={14}/></button>)}</div></>}</div></section>
 {role&&<><div className="role-hero"><div className="role-hero-left"><span className="role-category"><span/> {role.category.toUpperCase()}</span><h2>{role.name}</h2><p>{role.summary}</p><div className="role-hero-tags"><span><BookOpen size={13}/>{items.length} focus skills</span><span><Activity size={13}/>{role.languages.length} languages to learn</span><span><GraduationCap size={14}/>Career guide</span></div></div><div className="role-hero-side"><div className="readiness-circle" style={{'--progress':`${total?completed/total*100:0}%`} as CSSProperties}><div><b>{total?Math.round(completed/total*100):0}<small>%</small></b><span>READY</span></div></div><span className="readiness-caption">Your readiness</span></div><div className="role-hero-orb"/><div className="role-hero-lines"/></div>
 <div className="tabs-bar">{['Skills','Languages','Company insights'].map(tab=><button key={tab} onClick={()=>setActiveTab(tab)} className={activeTab===tab?'selected':''}>{tab}{tab==='Skills'&&<span className="tab-count">{items.length}</span>}</button>)}</div>
 {activeTab==='Skills'&&<div className="role-content-grid"><div className="skills-area"><div className="skills-top"><div><h3>Skills to build</h3><p>Check off what you already feel confident in.</p></div><span className="progress-mini">{completed} / {total} complete</span></div><div className="skill-groups">{grouped.map(group=>{const groupItems=items.filter(s=>s.group===group);return groupItems.length>0&&<div className="skill-group" key={group}><div className="group-heading"><span className={`group-dot ${group==='Core'?'dot-violet':group==='Tools'?'dot-blue':'dot-amber'}`}/><b>{group}</b><span>{groupItems.length} skills</span></div><div className="skill-list">{groupItems.map(s=><button key={s.name} className={`skill-row ${checked(s.name)?'skill-done':''}`} onClick={()=>void toggleSkill(s.name)}><span className={`skill-check ${checked(s.name)?'checked':''}`}>{checked(s.name)&&<Check size={12}/>}</span><span className="skill-text"><b>{s.name}</b><small>{s.detail}</small></span><ChevronRight size={15}/></button>)}</div></div>})}</div></div><aside className="panel language-aside"><div className="panel-heading"><div><h3>Language priorities</h3><p>A practical learning order</p></div><span className="soft-icon"><BookOpen size={15}/></span></div><div className="language-list">{[...role.languages].sort((a,b)=>a.order-b.order).map((l,i)=><div className="language-item" key={l.name}><span className={`language-rank rank-${i+1}`}>{String(i+1).padStart(2,'0')}</span><div><b>{l.name}</b><span>{l.reason}</span></div>{i===0&&<i className="start-here">START HERE</i>}</div>)}</div><div className="language-note"><Sparkles size={15}/><span>Go deep on one language first. Breadth comes with practice.</span></div><button className="mentor-link" onClick={()=>notify('Your mentor can turn these skills into a week-by-week plan.')}>Build my learning plan <ArrowRight size={14}/></button></aside></div>}
 {activeTab==='Languages'&&<div className="language-full panel"><div className="panel-heading"><div><h3>Your learning sequence</h3><p>Build fluency one layer at a time.</p></div><span className="soft-icon"><BookOpen size={15}/></span></div>{[...role.languages].sort((a,b)=>a.order-b.order).map((l,i)=><div className="language-full-row" key={l.name}><span className={`language-rank rank-${i+1}`}>{i+1}</span><div><span className="step-tag">{i===0?'START HERE':i===1?'NEXT UP':'THEN LEARN'}</span><h4>{l.name}</h4><p>{l.reason}</p></div><ArrowDownRight size={17}/></div>)}</div>}
 {activeTab==='Company insights'&&<><div className="guidance-note"><ShieldCheck size={16}/><span>General career guidance based on common role expectations. This is not official company policy.</span></div><div className="company-tabs">{['Google','Microsoft','Amazon'].map(c=><button key={c} className={company===c?'active':''} onClick={()=>setCompany(c)}><CompanyMark company={c}/>{c}</button>)}</div>{role.company_notes?.[company]&&<div className="company-insight-grid">{[{title:'Technical skills',icon:Zap,content:role.company_notes[company].technical.join(' · ')},{title:'DSA focus',icon:Target,content:role.company_notes[company].dsa},{title:'System design',icon:Activity,content:role.company_notes[company].systemDesign},{title:'Behavioral strengths',icon:MessageCircle,content:role.company_notes[company].behavioral}].map(x=><div className="panel insight-card" key={x.title}><div className="insight-icon"><x.icon size={16}/></div><h3>{x.title}</h3><p>{x.content}</p></div>)}</div>}</>}
 </>}
 </>}

function JobsPage({jobs,session,progress,reload,notify}:{jobs:Job[];session:any;progress:any;reload:()=>void;notify:(s:string)=>void}){
 const [company,setCompany]=useState('All companies');const [role,setRole]=useState('All roles');const [status,setStatus]=useState('All statuses');const [location,setLocation]=useState('');const [work,setWork]=useState('All work types');const [query,setQuery]=useState('');const [saving,setSaving]=useState('');
 const companies=['All companies',...Array.from(new Set(jobs.map(j=>j.company)))];const roles=['All roles',...Array.from(new Set(jobs.map(j=>j.role)))];const saved=new Set((progress.saved??[]).map((x:any)=>x.job_id));
 const filtered=useMemo(()=>jobs.filter(j=>(company==='All companies'||j.company===company)&&(role==='All roles'||j.role===role)&&(status==='All statuses'||j.status===status)&&(work==='All work types'||j.work_type===work)&&(!location||j.location.toLowerCase().includes(location.toLowerCase()))&&(!query||`${j.title} ${j.company} ${j.role} ${j.location}`.toLowerCase().includes(query.toLowerCase()))),[jobs,company,role,status,location,work,query]);
 async function toggle(j:Job){setSaving(j.id);try{await api(`/api/jobs/${j.id}/save`,session,{method:saved.has(j.id)?'DELETE':'POST'});reload();notify(saved.has(j.id)?'Removed from your saved jobs.':'Job saved to your journey.')}catch(e){notify((e as Error).message)}finally{setSaving('')}}
 const apiBase=(import.meta.env.VITE_API_URL as string|undefined)??'http://localhost:3001';
 return <><PageHeading eyebrow="FIND YOUR NEXT OPPORTUNITY" title="Job openings" subtitle="A curated starting point for roles worth exploring." action={<span className="jobs-live"><span className="live-dot"/>{jobs.length} seeded listings</span>}/><div className="job-toolbar"><div className="job-search"><Search size={16}/><input placeholder="Search titles, companies, locations…" value={query} onChange={e=>setQuery(e.target.value)}/><kbd>/</kbd></div><div className="filter-label"><Filter size={14}/> FILTERS</div><select value={company} onChange={e=>setCompany(e.target.value)} aria-label="Filter by company">{companies.map(x=><option key={x}>{x}</option>)}</select><select value={role} onChange={e=>setRole(e.target.value)} aria-label="Filter by role">{roles.map(x=><option key={x}>{x}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)} aria-label="Filter by status">{['All statuses','Upcoming','Open','Closing Soon','Closed'].map(x=><option key={x}>{x}</option>)}</select><select value={work} onChange={e=>setWork(e.target.value)} aria-label="Filter by work type">{['All work types','On-site','Remote','Hybrid'].map(x=><option key={x}>{x}</option>)}</select><input className="location-filter" placeholder="Location" value={location} onChange={e=>setLocation(e.target.value)}/></div><div className="jobs-result-line"><span>Showing <b>{filtered.length}</b> opportunities</span><span><ArrowDownRight size={13}/> Sorted by closing date</span></div>
 <div className="jobs-grid">{filtered.map(j=><article className="job-card" key={j.id}><div className="job-card-top"><CompanyMark company={j.company}/><div className="job-company"><b>{j.company}</b><span>{j.location}</span></div><span className={`status status-${j.status.toLowerCase().replace(' ','-')}`}>{j.status}</span></div><h3>{j.title}</h3><div className="job-role-tag">{j.role}</div><div className="job-attributes"><span><BriefcaseBusiness size={14}/>{j.experience}</span><span><Compass size={14}/>{j.work_type}</span></div><div className="job-dates"><div><small>APPLICATION OPENS</small><b>{prettyDate(j.opens_at)}</b></div><div><small>APPLICATION CLOSES</small><b className={j.status==='Closing Soon'?'urgent':''}>{prettyDate(j.closes_at)}</b></div><a className="calendar-link" href={`${apiBase}/api/jobs/${j.id}/calendar.ics`} title="Add deadline to calendar"><CalendarDays size={15}/><span>Add reminder</span></a></div><div className="job-card-actions"><button className={`save-btn ${saved.has(j.id)?'saved':''}`} onClick={()=>void toggle(j)} disabled={saving===j.id}>{saved.has(j.id)?<Check size={15}/>:<Bookmark size={15}/>} {saved.has(j.id)?'Saved':'Save'}</button><a className={`apply-btn ${j.status==='Closed'?'disabled':''}`} href={j.status==='Closed'?'#':j.apply_url} target={j.status==='Closed'?undefined:'_blank'} rel="noreferrer" onClick={e=>{if(j.status==='Closed'){e.preventDefault();notify('This application window has closed.')}}}>{j.status==='Closed'?'Closed':'View opportunity'}{j.status==='Closed'?null:<ExternalLink size={14}/>}</a></div></article>)}{!filtered.length&&<div className="empty-state jobs-empty"><Search size={25}/><h3>No matching openings</h3><p>Try widening a filter or searching another role.</p><button className="text-link" onClick={()=>{setCompany('All companies');setRole('All roles');setStatus('All statuses');setLocation('');setWork('All work types');setQuery('')}}>Clear filters <X size={14}/></button></div>}</div></>}

function Mentor({roles,profile,session,progress,setProgress,notify}:{roles:Role[];profile:UserProfile;session:any;progress:any;setProgress:(v:any)=>void;notify:(s:string)=>void}){
 const [roleId,setRoleId]=useState('');const [months,setMonths]=useState(6);const [companies,setCompanies]=useState<string[]>(profile.target_companies??[]);const [skillNames,setSkillNames]=useState<string[]>([]);const [steps,setSteps]=useState<Step[]>([]);const [chat,setChat]=useState<{from:'mentor'|'you';text:string}[]>([]);const [prefsLoaded,setPrefsLoaded]=useState(false);const [question,setQuestion]=useState('');const [busy,setBusy]=useState(false);const role=roles.find(r=>r.id===roleId);
 useEffect(()=>{if(roles.length&&!roleId)setRoleId(roles.find(r=>r.name===profile.target_role)?.id??roles[0].id)},[roles,roleId,profile.target_role]);
 useEffect(()=>{const stored=progress.roadmap??[];if(stored.length)setSteps(stored.map((s:any)=>({...s,resources:Array.isArray(s.resources)?s.resources:[]})))},[progress.roadmap]);
 useEffect(()=>{if(prefsLoaded||!roles.length)return;const prefs=progress.mentorPreferences;if(prefs){setRoleId(prefs.role_id);setSkillNames(prefs.skill_names??[]);setCompanies(prefs.companies??[]);setMonths(prefs.months??6)}setChat((progress.mentorMessages??[]).map((m:any)=>({from:m.sender,text:m.content})));setPrefsLoaded(true)},[roles,progress.mentorPreferences,progress.mentorMessages,prefsLoaded]);
 const stepsPercent=steps.length?Math.round(steps.filter(s=>s.completed).length/steps.length*100):0;
 async function createRoadmap(){if(!role)return;setBusy(true);try{const result=await api<Step[]>('/api/mentor/roadmap',session,{method:'POST',body:JSON.stringify({role:role.name,skills:skillNames,companies,months})});setSteps(result);setProgress({...progress,roadmap:result});setChat([{from:'mentor',text:`I’ve mapped a ${months}-month path toward becoming a ${role.name}. We’ll move through foundation, role skills, a portfolio project, interview practice, and applications. You already know ${skillNames.length?skillNames.join(', '):'you are ready to begin'}—we’ll build from there. Take it one week at a time; progress matters more than pace.`}]);notify('Your personalized roadmap is ready.')}catch(e){notify((e as Error).message)}finally{setBusy(false)}}
 async function markStep(step:Step){const next=steps.map(x=>x.id===step.id?{...x,completed:!x.completed,completed_at:!x.completed?new Date().toISOString():null}:x);setSteps(next);setProgress({...progress,roadmap:next});if(!role)return;try{await api('/api/progress',session,{method:'PUT',body:JSON.stringify({role_id:role.id,checklist:[],roadmap:next.map(x=>({id:x.id,completed:x.completed}))})})}catch(e){notify((e as Error).message)}}
 async function ask(e:FormEvent){e.preventDefault();if(!question.trim()||!role)return;const q=question.trim();setQuestion('');setChat(c=>[...c,{from:'you',text:q}]);setBusy(true);try{const answer=await api<{answer:string}>('/api/mentor/chat',session,{method:'POST',body:JSON.stringify({question:q,role:role.name,companies})});setChat(c=>[...c,{from:'mentor',text:answer.answer}])}catch(err){notify((err as Error).message)}finally{setBusy(false)}}
 function toggleCompany(c:string){setCompanies(x=>x.includes(c)?x.filter(y=>y!==c):[...x,c])}
 return <><PageHeading eyebrow="YOUR PERSONAL CAREER COACH" title="Meet your AI mentor" subtitle="A thoughtful plan, built around where you want to go." action={<span className="mentor-powered"><Sparkles size={14}/> Powered by Career Navigator</span>}/><div className="mentor-layout"><aside className="mentor-config panel"><div className="config-head"><div className="mentor-avatar"><Sparkles size={19}/><i/></div><div><b>Your path, your pace</b><span>Personalize your roadmap</span></div></div><div className="mentor-journey-summary"><div><b>YOUR JOURNEY</b><span>{steps.filter(s=>s.completed).length} of {steps.length} steps complete</span></div><div className="mentor-journey-track"><i style={{width:`${stepsPercent}%`}}/></div><div className="mentor-phase-dots">{["Foundation","Core Skills","Projects","Interview Prep","Applications"].map((x,i)=><span key={x} className={steps[i]?.completed?"done":""} title={`${x}${steps[i]?.completed?" complete":""}`}/>)}</div></div><label className="field-label">TARGET ROLE<select value={roleId} onChange={e=>setRoleId(e.target.value)}>{roles.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><div className="field-label">WHAT DO YOU ALREADY KNOW?<span className="field-sub">Choose skills you have some experience with</span><div className="mentor-skill-list">{(role?.skills??[]).map(s=><button key={s.name} onClick={()=>setSkillNames(x=>x.includes(s.name)?x.filter(y=>y!==s.name):[...x,s.name])} className={skillNames.includes(s.name)?'chosen':''}><span>{skillNames.includes(s.name)&&<Check size={11}/>}</span>{s.name}</button>)}</div></div><div className="field-label">COMPANIES ON YOUR RADAR<div className="company-checks">{['Google','Microsoft','Amazon'].map(c=><button key={c} className={companies.includes(c)?'chosen':''} onClick={()=>toggleCompany(c)}><CompanyMark company={c}/>{c}<span className="check-sq">{companies.includes(c)&&<Check size={11}/>}</span></button>)}</div></div><div className="field-label">YOUR TIMELINE<div className="timeline-options">{[3,6,12].map(n=><button className={months===n?'selected':''} onClick={()=>setMonths(n)} key={n}><b>{n}</b><span>months</span></button>)}</div></div><button className="btn-primary full-btn" onClick={()=>void createRoadmap()} disabled={busy}>{busy?<span className="spinner light-spinner"/>:<Sparkles size={15}/>} {steps.length?'Refresh my roadmap':'Create my roadmap'}<ArrowRight size={15}/></button><p className="config-foot"><ShieldCheck size={13}/> Your plan is private and can be changed anytime.</p></aside>
 <section className="mentor-main"><div className="mentor-chat panel"><div className="chat-head"><div className="chat-head-avatar"><Sparkles size={16}/></div><div><b>Navigator</b><span><i/> Here to help you move forward</span></div><MoreHorizontal size={18} className="chat-more" aria-hidden="true"/></div><div className="chat-body">{chat.length===0?<div className="chat-welcome"><div className="welcome-spark"><Sparkles size={23}/></div><span className="step-tag">A BETTER WAY FORWARD</span><h2>Let’s make your next step<br/>feel a little clearer.</h2><p>Share your goals and I’ll create a practical roadmap you can make your own.</p><div className="suggestion-prompts">{['What should I focus on first?','How do I build a standout project?','How should I prepare for interviews?'].map(x=><button key={x} onClick={()=>setQuestion(x)}>{x}<ArrowUpRight size={13}/></button>)}</div></div>:<div className="chat-messages">{chat.map((m,i)=><div className={`chat-message ${m.from}`} key={i}>{m.from==='mentor'?<div className="message-avatar"><Sparkles size={13}/></div>:null}<div className="message-content"><small>{m.from==='mentor'?'NAVIGATOR':'YOU'}</small><p>{m.text}</p></div></div>)}{busy&&<div className="typing"><i/><i/><i/> Navigator is thinking</div>}</div>}</div><form className="chat-input-row" onSubmit={ask}><input value={question} onChange={e=>setQuestion(e.target.value)} placeholder="Ask a follow-up about your career path…" aria-label="Ask your mentor"/><button aria-label="Send message" disabled={!question.trim()||busy}><Send size={16}/></button><div className="chat-input-hint"><span>Specific questions get the most helpful guidance.</span><kbd>↵</kbd></div></form></div>
 <div className="roadmap-section"><div className="roadmap-heading"><div><span className="eyebrow">YOUR PERSONALIZED PLAN</span><h2>Your roadmap</h2></div>{steps.length>0&&<div className="roadmap-progress"><div><b>{stepsPercent}%</b><span>complete</span></div><div className="progress-track"><i style={{width:`${stepsPercent}%`}}/></div></div>}</div>{steps.length? <div className="roadmap-list">{steps.map((s,i)=><article className={`roadmap-step ${s.completed?'complete':''}`} key={s.id}><div className="roadmap-step-left"><div className={`roadmap-node ${s.completed?'complete':''}`}>{s.completed?<Check size={14}/>:String(i+1).padStart(2,'0')}</div>{i<steps.length-1&&<div className="roadmap-connector"/>}</div><div className="roadmap-step-card"><div className="roadmap-card-top"><span className="step-tag">{s.phase.toUpperCase()}</span><span><Clock3 size={12}/>{s.estimate}</span></div><h3>{s.title}</h3><p>{s.goal}</p><div className="resource-row"><BookOpen size={13}/>{s.resources?.map((r,i)=><span key={r}><a href={`https://www.google.com/search?q=${encodeURIComponent(r)}`} target="_blank" rel="noreferrer">{r}<ExternalLink size={11}/></a>{i<s.resources.length-1&&<i>·</i>}</span>)}</div><button className={`complete-btn ${s.completed?'marked':''}`} onClick={()=>void markStep(s)}>{s.completed?<><Check size={14}/> Completed</>:<><CheckCircle2 size={14}/> Mark complete</>}</button></div></article>)}</div>:<div className="roadmap-empty panel"><div className="road-empty-art"><div><Target size={22}/></div><span/><i/></div><h3>Every big goal starts with a first step.</h3><p>Choose your role, share what you know, and I’ll shape a roadmap just for you.</p><button className="btn-primary" onClick={()=>void createRoadmap()} disabled={busy}><Sparkles size={15}/> Build my roadmap <ArrowRight size={15}/></button></div>}</div></section></div></>}

function Journey({profile,progress,jobs,setPage}:{profile:UserProfile;progress:any;jobs:Job[];setPage:(p:Page)=>void}){const activity=weeklyActivity(progress);const steps=progress.roadmap??[];const completed=steps.filter((x:any)=>x.completed).length;const skills=(progress.checklist??[]).filter((x:any)=>x.completed).length;const saved=(progress.saved??[]).map((x:any)=>x.jobs).filter(Boolean).sort((a:any,b:any)=>a.closes_at.localeCompare(b.closes_at));const next=steps.filter((x:any)=>!x.completed).slice(0,3);return <><PageHeading eyebrow="YOUR PROGRESS, AT A GLANCE" title="My journey" subtitle={profile.target_role?`Your progress toward ${profile.target_role}.`:'Your growth, all in one place.'} action={<button className="btn-primary" onClick={()=>setPage('mentor')}><Sparkles size={15}/> {steps.length?'Open my roadmap':'Plan my next step'}</button>}/><div className="journey-summary"><div className="journey-summary-main"><div className="journey-summary-copy"><span className="step-tag">PERSONAL GROWTH</span><h2>{completed?`You’ve completed ${completed} meaningful step${completed===1?'':'s'}.`:'Every step forward counts.'}</h2><p>{steps.length?`Your ${steps[0]?.role_id?'career':'personal'} roadmap is a living plan. Keep moving at a pace that works for you.`:'Build a personalized roadmap and turn your goals into a clear plan of action.'}</p><button className="btn-primary" onClick={()=>setPage(steps.length?'mentor':'roles')}>{steps.length?'Continue your roadmap':'Find your direction'}<ArrowRight size={15}/></button></div><div className="journey-ring" style={{'--progress':`${steps.length?completed/steps.length*100:0}%`} as CSSProperties}><div><b>{steps.length?Math.round(completed/steps.length*100):0}<small>%</small></b><span>OVERALL</span></div></div></div><div className="journey-summary-stats"><div><span className="summary-stat-icon violet"><CheckCircle2 size={15}/></span><span><b>{completed}<small>/{steps.length}</small></b><i>Roadmap steps complete</i></span></div><div><span className="summary-stat-icon amber"><Zap size={15}/></span><span><b>{skills}</b><i>Skills mastered</i></span></div><div><span className="summary-stat-icon blue"><Bookmark size={15}/></span><span><b>{saved.length}</b><i>Saved opportunities</i></span></div></div></div><div className="journey-grid"><section className="panel journey-chart"><div className="panel-heading"><div><h3>Your momentum</h3><p>Activity over the past week</p></div><span className="select-lite">This week <ChevronDown size={14}/></span></div><div className="chart-wrap journey-chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity} margin={{top:12,right:8,left:-18,bottom:0}}><defs><linearGradient id="journeyGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7160e8" stopOpacity={.18}/><stop offset="100%" stopColor="#7160e8" stopOpacity={0}/></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--line-soft)" strokeDasharray="3 5"/><XAxis dataKey="day" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'var(--muted)'}} dy={10}/><Tooltip contentStyle={{border:'1px solid var(--line)',borderRadius:12,background:'var(--surface)',fontSize:12}}/><Area type="monotone" dataKey="done" stroke="#7160e8" strokeWidth={2.5} fill="url(#journeyGradient)"/></AreaChart></ResponsiveContainer></div></section><section className="panel actions-panel"><div className="panel-heading"><div><h3>Next three actions</h3><p>Small moves, clear momentum</p></div><span className="soft-icon"><Target size={15}/></span></div>{next.length?next.map((x:any,i:number)=><button className="action-item" key={x.id} onClick={()=>setPage('mentor')}><span className="action-index">0{i+1}</span><span><b>{x.title}</b><small>{x.phase} · {x.estimate}</small></span><ChevronRight size={15}/></button>):<div className="empty-mini"><div className="empty-glyph"><Target size={18}/></div><b>Your next steps will live here</b><span>Ask your mentor to create a roadmap.</span><button className="text-link" onClick={()=>setPage('mentor')}>Meet your mentor <ArrowRight size={13}/></button></div>}</section></div><div className="section-row"><div><h2 className="section-title">Saved opportunities</h2><p className="section-sub">Keep an eye on the deadlines that matter</p></div><button className="text-link" onClick={()=>setPage('jobs')}>Explore openings <ArrowRight size={14}/></button></div>{saved.length?<div className="saved-list">{saved.slice(0,4).map((j:any)=><div className="saved-row" key={j.id}><CompanyMark company={j.company}/><div className="saved-title"><b>{j.title}</b><span>{j.company} · {j.location}</span></div><span className={`status status-${jobs.find(x=>x.id===j.id)?.status.toLowerCase().replace(' ','-')??'open'}`}>{jobs.find(x=>x.id===j.id)?.status??'Open'}</span><span className="saved-deadline"><CalendarDays size={14}/>{prettyDate(j.closes_at)}</span><button className="icon-btn" aria-label="View saved openings" onClick={()=>setPage('jobs')}><ArrowUpRight size={16}/></button></div>)}</div>:<div className="empty-state"><Bookmark size={21}/><b>Nothing saved yet</b><span>Save a promising opening and its deadline will show up here.</span><button className="text-link" onClick={()=>setPage('jobs')}>Browse opportunities <ArrowRight size={14}/></button></div>}</>}

function ProfilePage({profile,save,signOut}:{profile:UserProfile;save:(p:UserProfile)=>void;signOut:()=>void}){const [draft,setDraft]=useState(profile);const companies=['Google','Microsoft','Amazon'];useEffect(()=>setDraft(profile),[profile]);useEffect(()=>{document.documentElement.dataset.theme=draft.theme||'light';return()=>{document.documentElement.dataset.theme=profile.theme||'light'}},[draft.theme,profile.theme]);function set<K extends keyof UserProfile>(key:K,value:UserProfile[K]){setDraft(x=>({...x,[key]:value}))}function toggle(c:string){setDraft(x=>({...x,target_companies:x.target_companies.includes(c)?x.target_companies.filter(y=>y!==c):[...x.target_companies,c]}))}return <><PageHeading eyebrow="MAKE IT YOURS" title="Profile & settings" subtitle="A little context helps us make your guidance more useful." action={<button className="btn-subtle" onClick={signOut}><LogOut size={15}/> Sign out</button>}/><div className="profile-layout"><aside className="panel profile-card"><div className="profile-avatar-large">{initials(profile.name)}</div><h3>{profile.name||'Your name'}</h3><p>{profile.college||'Your college'}{profile.year?` · ${profile.year}`:''}</p><div className="profile-role-pill"><Target size={13}/>{profile.target_role||'No target role yet'}</div><div className="profile-card-foot"><ShieldCheck size={14}/> Private to your account</div></aside><div className="profile-settings"><section className="panel settings-card"><div className="settings-title"><div className="settings-icon"><GraduationCap size={17}/></div><div><h3>Your background</h3><p>Help us tailor the guidance to you</p></div></div><div className="settings-fields"><label>Full name<input value={draft.name} onChange={e=>set('name',e.target.value)} placeholder="Your name"/></label><label>College or university<input value={draft.college} onChange={e=>set('college',e.target.value)} placeholder="Where you study"/></label><label>Branch or major<input value={draft.branch} onChange={e=>set('branch',e.target.value)} placeholder="e.g. Computer Science"/></label><label>Year of study<select value={draft.year} onChange={e=>set('year',e.target.value)}><option value="">Select your year</option>{['1st year','2nd year','3rd year','4th year','Graduate','Other'].map(x=><option key={x}>{x}</option>)}</select></label></div></section><section className="panel settings-card"><div className="settings-title"><div className="settings-icon violet"><Target size={17}/></div><div><h3>Career direction</h3><p>Tell us what you’re working toward</p></div></div><label className="wide-field">Target role<select value={draft.target_role} onChange={e=>set('target_role',e.target.value)}><option value="">Choose a role</option>{['AI/ML Engineer','Data Scientist','Machine Learning Engineer','Full Stack Developer','Backend Developer','Frontend Developer','DevOps Engineer','Cloud Engineer','Cybersecurity Analyst','Data Analyst'].map(x=><option key={x}>{x}</option>)}</select></label><div className="field-label company-target-label">COMPANIES ON YOUR RADAR<div className="profile-company-picks">{companies.map(c=><button key={c} className={draft.target_companies.includes(c)?'selected':''} onClick={()=>toggle(c)}><CompanyMark company={c}/>{c}{draft.target_companies.includes(c)&&<Check size={13}/>}</button>)}</div></div></section><section className="panel settings-card theme-settings"><div className="settings-title"><div className="settings-icon"><Sun size={17}/></div><div><h3>Appearance</h3><p>Choose a theme that feels right to you</p></div></div><div className="theme-switcher"><button className={draft.theme==='light'?'selected':''} onClick={()=>set('theme','light')}><Sun size={16}/><span><b>Light</b><small>Bright and easy to read</small></span>{draft.theme==='light'&&<Check size={15}/>}</button><button className={draft.theme==='dark'?'selected':''} onClick={()=>set('theme','dark')}><Moon size={16}/><span><b>Dark</b><small>Soft on the eyes</small></span>{draft.theme==='dark'&&<Check size={15}/>}</button></div></section><div className="profile-save-row"><span>Your progress saves securely to your account.</span><button className="btn-primary" onClick={()=>save(draft)}><Check size={15}/> Save changes</button></div></div></div></>}
